const genericModule = (id) => ({title:id.replace(/-/g,' ').replace(/\b\w/g,x=>x.toUpperCase()),eyebrow:'PLATFORM MODULE',status:'ROADMAP',description:'This workspace is present in the platform architecture and is being developed through validated, traceable increments.',cards:[['STATUS','Under development','Functionality is not claimed until it is implemented and tested'],['DATA','Project context and provenance','Required before professional use'],['NEXT','Domain-pack integration','Solver, security and benchmark work remain']]});
function createBlankModel() { modelRoot = new THREE.Group(); modelRoot.name = 'Blank engineering model'; scene.add(modelRoot); box('Reference origin', [.18,.18,.18], [0,0,0], materials.lime, {category:'Reference',level:'origin',dimensions:'0.18 m marker',material:'Reference geometry'}); $('modelState').textContent = 'Blank model · define levels and geometry'; }
function ensureModel(example=false) { const wanted=example?'Mbarara Smart Residence / MBR-26-001':'Blank engineering model'; if (!modelRoot || modelRoot.name !== wanted) { if(modelRoot){scene.remove(modelRoot); editable.length=0;} if (example) { createResidence(); $('modelState').textContent = 'Example model loaded · 34 editable components'; } else createBlankModel(); } }
function setContext(title, subtitle, project=false) { $('pageTitle').textContent=title; $('pageSubtitle').textContent=subtitle; $('projectStrip').classList.toggle('hidden', !project); }
function chartBars(items, unit) { const max=Math.max(...items.map(x=>Math.abs(x.value)),1); return `<div class="result-chart" aria-label="Calculation result chart">${items.map(x=>`<div class="bar-row"><span>${x.label}</span><div><i style="width:${Math.max(4,Math.abs(x.value)/max*100)}%"></i></div><b>${x.value} ${unit}</b></div>`).join('')}</div>`; }
function svgWater(d){ const loss=d.outputs.headloss_m, rise=d.inputs.elevation_rise_m, residual=d.outputs.residual_head_m; return `<svg class="engineering-diagram" viewBox="0 0 760 250" role="img" aria-label="Single pipe schematic and hydraulic grade line"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 z" fill="#d9ff4a"/></marker></defs><line x1="80" y1="70" x2="680" y2="150" stroke="#d9ff4a" stroke-width="5" marker-end="url(#arrow)"/><line x1="80" y1="45" x2="680" y2="125" stroke="#59d7b2" stroke-width="2" stroke-dasharray="8 6"/><line x1="80" y1="210" x2="680" y2="210" stroke="#6f8580" stroke-width="2"/><circle cx="80" cy="70" r="14" fill="#4f8890"/><circle cx="680" cy="150" r="14" fill="#c79a58"/><text x="52" y="35" fill="#e7eee8" font-size="13">RESERVOIR H=${d.inputs.reservoir_head_m} m</text><text x="600" y="185" fill="#e7eee8" font-size="13">OUTLET</text><text x="290" y="98" fill="#d9ff4a" font-size="13">FLOW → ${d.outputs.flow_lps} L/s</text><text x="290" y="122" fill="#59d7b2" font-size="12">hydraulic grade line</text><text x="300" y="232" fill="#9aa9a3" font-size="12">Pipe L=${d.inputs.pipe_length_m} m · Ø=${d.inputs.pipe_diameter_mm} mm · head loss=${loss} m · rise=${rise} m · residual=${residual} m</text></svg>`; }
function svgAir(d){ const w=520,h=180, flow=d.outputs.flow_m3_s, v=d.outputs.inlet_velocity_m_s; return `<svg class="engineering-diagram" viewBox="0 0 760 250" role="img" aria-label="Scaled room airflow diagram"><defs><marker id="airArrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0,0 L8,4 L0,8 z" fill="#6bd7ff"/></marker></defs><rect x="110" y="45" width="${w/1.4}" height="${h/1.5}" fill="#102126" stroke="#6f8580" stroke-width="3"/><rect x="110" y="108" width="18" height="35" fill="#59d7b2"/><rect x="464" y="78" width="18" height="35" fill="#c79a58"/><path d="M130 125 C220 85 310 160 460 96" fill="none" stroke="#6bd7ff" stroke-width="4" marker-end="url(#airArrow)"/><text x="100" y="28" fill="#e7eee8" font-size="13">ROOM ${d.inputs.room_length_m} × ${d.inputs.room_width_m} × ${d.inputs.room_height_m} m</text><text x="90" y="165" fill="#59d7b2" font-size="12">INLET</text><text x="445" y="135" fill="#c79a58" font-size="12">OUTLET</text><text x="110" y="215" fill="#9aa9a3" font-size="12">Q=${flow} m³/s · inlet velocity=${v} m/s · ACH=${d.inputs.air_changes_per_hour} · ΔT=${d.outputs.sensible_temperature_rise_c} °C</text></svg>`; }
function svgEnergy(d){ const g=d.outputs.annual_generation_kwh, grid=d.outputs.grid_import_kwh, exp=d.outputs.exported_kwh; return `<svg class="engineering-diagram" viewBox="0 0 760 230" role="img" aria-label="Annual energy balance diagram"><line x1="90" y1="185" x2="690" y2="185" stroke="#6f8580"/><line x1="90" y1="35" x2="90" y2="185" stroke="#6f8580"/><path d="M90 160 C180 130 230 95 320 115 S470 55 690 75" fill="none" stroke="#d9ff4a" stroke-width="4"/><path d="M90 175 C220 168 350 150 470 155 S590 145 690 150" fill="none" stroke="#6bd7ff" stroke-width="3"/><text x="100" y="28" fill="#e7eee8" font-size="13">ANNUAL ENERGY BALANCE · kWh/year</text><text x="510" y="66" fill="#d9ff4a" font-size="12">PV generation ${g}</text><text x="510" y="143" fill="#6bd7ff" font-size="12">Grid import ${grid}</text><text x="100" y="215" fill="#9aa9a3" font-size="12">Exported ${exp} kWh · curves are annualized screening summaries, not hourly weather data</text></svg>`; }
function requiredNumbers(ids, labels, mins){ const values=[]; for(let i=0;i<ids.length;i++){ const raw=$(ids[i]).value.trim(); if(raw==='') return {error:`${labels[i]} is required.`}; const value=Number(raw); if(!Number.isFinite(value)) return {error:`${labels[i]} must be a finite number.`}; if(value<mins[i]) return {error:`${labels[i]} must be ${mins[i]===0?'zero or greater':'greater than '+mins[i]}.`}; values.push(value); } return {values}; }
async function cloudUpsertProject(data){ if(!currentUser || !data?.name) return null; const payload={name:data.name,discipline:data.discipline||null,location:data.location||null,metadata:{inputs:data.inputs||{},local_id:data.id||null}}; const query=data.id && /^[0-9a-f-]{36}$/i.test(data.id) ? supabase.from('projects').update(payload).eq('id',data.id).select().single() : supabase.from('projects').insert(payload).select().single(); const {data:row,error}=await query; if(error){console.warn('Cloud project save failed',error.message);return null;} return row; }
async function cloudSaveCalculation(projectId,data){ if(!currentUser || !projectId || !/^[0-9a-f-]{36}$/i.test(projectId)) return; const {data:rev}=await supabase.from('project_revisions').insert({project_id:projectId,revision_number:Date.now(),inputs:data.inputs||{},status:'calculated'}).select().single(); await supabase.from('calculations').insert({project_id:projectId,revision_id:rev?.id||null,solver:data.record?.solver||'AxiomForge screening',inputs:data.inputs||{},outputs:data.outputs||{},record:data.record||{}}); }
function saveProject(data){ const key='axiomforge.projects.v1'; const list=JSON.parse(localStorage.getItem(key)||'[]'); const existing=list.findIndex(x=>x.id===data.id); if(existing>=0){ const prior=list[existing]; list[existing]={...prior,...data,name:prior.name||data.name,location:prior.location||data.location,discipline:prior.discipline||data.discipline}; } else list.unshift(data); localStorage.setItem(key,JSON.stringify(list.slice(0,50))); localStorage.setItem('axiomforge.activeProject',data.id); if(currentUser) cloudUpsertProject(data).then(row=>{ if(row && data.record) cloudSaveCalculation(row.id,{...data,outputs:data.outputs||{}}); }); }
function getProjects(){ try{return JSON.parse(localStorage.getItem('axiomforge.projects.v1')||'[]')}catch{return []} }
function formField(id,label,unit,attrs='') { return `<label>${label}<input id="${id}" type="number" required ${attrs}><small>${unit}</small></label>`; }
async function initAuth(){ const {data}=await supabase.auth.getSession(); currentUser=data.session?.user||null; authReady=true; updateAuthNav(); supabase.auth.onAuthStateChange((_event,session)=>{currentUser=session?.user||null; updateAuthNav();}); }
function updateAuthNav(){ const b=document.querySelector('[data-view="account"]'); if(b) b.textContent=currentUser?`◎ ${currentUser.email}`:'◎ Sign in / account'; }
function renderAccountWorkspace(host){ const local=getProjects(); host.innerHTML=currentUser?`<div class="module-header"><div><span class="eyebrow">SECURE ACCOUNT</span><h2>Cloud account</h2><p>Signed in as ${currentUser.email}. Private Supabase project records use Row Level Security and are isolated to this account.</p></div><span class="status-chip">AUTHENTICATED</span></div><div class="home-actions"><button class="primary-button" id="migrateLocal">MIGRATE LOCAL PROJECTS</button><button class="tool-button" id="signOut">SIGN OUT</button></div><div id="authMessage" class="module-disclaimer">Local projects are preserved. Migration creates new cloud records and does not overwrite local data.</div>`:`<div class="module-header"><div><span class="eyebrow">SECURE ACCOUNT</span><h2>Sign in to save across devices</h2><p>Authentication is handled by Supabase Auth. Only the publishable browser key is present in this application; service credentials remain server-side.</p></div><span class="status-chip">AUTH REQUIRED</span></div><div class="input-grid domain-form"><label>Email<input id="authEmail" type="email" autocomplete="email" required placeholder="you@example.com"></label><label>Password<input id="authPassword" type="password" autocomplete="current-password" required placeholder="Minimum 6 characters"></label></div><div class="module-actions"><button class="primary-button" id="signIn">SIGN IN</button><button class="tool-button" id="signUp">CREATE ACCOUNT</button></div><div id="authMessage" class="module-disclaimer">Create an account or sign in to save projects and calculation histories privately.</div>`; if(currentUser){$('signOut').onclick=async()=>{await supabase.auth.signOut();renderWorkspace('account');}; $('migrateLocal').onclick=migrateLocalProjects;} else { $('signIn').onclick=()=>submitAuth('signin'); $('signUp').onclick=()=>submitAuth('signup'); } }
async function submitAuth(mode){ const email=$('authEmail').value.trim(), password=$('authPassword').value; const msg=$('authMessage'); if(!email||!password){msg.textContent='Email and password are required.';return;} msg.textContent='Contacting Supabase Auth…'; const result=mode==='signup'?await supabase.auth.signUp({email,password}):await supabase.auth.signInWithPassword({email,password}); if(result.error){msg.textContent=result.error.message;return;} msg.textContent=mode==='signup'?'Account created. Check your email if confirmation is enabled.':'Signed in successfully.'; if(mode==='signin'&&result.data.session) renderWorkspace('account'); }
async function migrateLocalProjects(){ const msg=$('authMessage'); const local=getProjects(); if(!local.length){msg.textContent='No local projects are available to migrate.';return;} let migrated=0; for(const project of local){ if(/^[0-9a-f-]{36}$/i.test(project.id)) continue; const row=await cloudUpsertProject(project); if(row){ project.cloudId=row.id; if(project.record) await cloudSaveCalculation(row.id,project); migrated++; } } localStorage.setItem('axiomforge.projects.v1',JSON.stringify(local)); msg.textContent=`Migration complete: ${migrated} local project record(s) copied as new private cloud records. Local data was preserved.`; }
function renderImportWorkspace(host){ host.innerHTML=`<div class="module-header"><div><span class="eyebrow">SECURE DATA INPUT</span><h2>Upload / import engineering data</h2><p>Validated file intake for CSV, JSON, XLSX, PDF, images, DXF and IFC metadata. Full parsing adapters are added only where supported.</p></div><span class="status-chip">${currentUser?'PRIVATE STORAGE READY':'SIGN IN REQUIRED'}</span></div><label class="file-drop">Select a file<input id="engineeringFile" type="file" accept=".csv,.json,.xlsx,.xls,.pdf,.png,.jpg,.jpeg,.dxf,.ifc"></label><div id="filePreview" class="result-panel">No file selected. Maximum upload size: 25 MB.</div><div class="module-actions"><button class="primary-button" id="uploadEngineeringFile" ${currentUser?'':'disabled'}>UPLOAD TO PRIVATE STORAGE</button></div><div class="module-disclaimer">CSV and JSON receive an in-browser preview. PDF, IFC, DXF and XLSX are stored with metadata in this increment; validated parsing adapters remain explicitly marked as foundation work.</div>`; $('engineeringFile').onchange=previewEngineeringFile; $('uploadEngineeringFile').onclick=uploadEngineeringFile; }
async function previewEngineeringFile(){ const file=$('engineeringFile').files[0], out=$('filePreview'); if(!file){out.textContent='No file selected.';return;} const allowed=/\.(csv|json|xlsx?|pdf|png|jpe?g|dxf|ifc)$/i.test(file.name); if(!allowed||file.size>25*1024*1024){out.textContent='Rejected: supported formats only, maximum 25 MB.';return;} if(/\.(csv|json)$/i.test(file.name)){ const text=await file.slice(0,20000).text(); out.innerHTML=`<strong>${file.name}</strong> · ${(file.size/1024).toFixed(1)} KB<pre class="data-preview">${text.replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]))}</pre>`; } else out.textContent=`${file.name} · ${(file.size/1024).toFixed(1)} KB · ${file.type||'application/octet-stream'} · metadata preview only`; }
async function uploadEngineeringFile(){ const file=$('engineeringFile').files[0], out=$('filePreview'); if(!file){out.textContent='Select a file before uploading.';return;} if(!currentUser){out.textContent='Sign in before uploading private files.';return;} const projects=getProjects(); const active=projects.find(x=>x.id===localStorage.getItem('axiomforge.activeProject')); if(!active||!/^[0-9a-f-]{36}$/i.test(active.id)){out.textContent='Create or reopen a cloud project before uploading a private file.';return;} const path=`${currentUser.id}/${active.id}/${crypto.randomUUID()}-${file.name}`; const {error}=await supabase.storage.from('engineering-files').upload(path,file,{contentType:file.type||'application/octet-stream',upsert:false}); if(error){out.textContent=`Upload failed: ${error.message}`;return;} const meta={project_id:active.id,storage_path:path,filename:file.name,mime_type:file.type||'application/octet-stream',byte_size:file.size,metadata:{extension:file.name.split('.').pop().toLowerCase()}}; const saved=await supabase.from('project_files').insert(meta); out.textContent=saved.error?`File stored but metadata save failed: ${saved.error.message}`:`Private upload complete: ${file.name}`; }
async function renderWorkspace(view) {
  const host=$('moduleWorkspace'); const studio=document.querySelector('.studio-grid'); const analysis=document.querySelector('.analysis-grid');
  if(view==='model'){ ensureModel(exampleRequested); if(exampleRequested){ setContext('Mbarara Smart Residence · P02','Example project · provisional editable BIM reconstruction',true); $('projectRef').textContent='MBR-26-001'; } else { setContext('BIM / CAD Studio','Blank modeling environment · define project geometry and units before modeling.',false); } exampleRequested=false; analysis.classList.remove('hidden'); $('projectLocation').textContent='Mbarara, Uganda'; $('projectBasis').textContent='Written brief · example'; $('projectStatus').textContent='Example / provisional'; $('projectDisclaimer').textContent='NOT CONSTRUCTION-APPROVED'; host.classList.add('hidden'); studio.classList.remove('hidden'); return; }
  host.classList.remove('hidden'); studio.classList.add('hidden'); analysis.classList.add('hidden'); setContext(view==='overview'?'Engineering workspace':(MODULES[view]||genericModule(view)).title, view==='overview'?'Start with your own project or data.':'User data is required before analysis.');
  if(view==='overview') { host.innerHTML=`<div class="home-hero"><span class="eyebrow">GENERAL ENGINEERING PLATFORM</span><h2>Start with your engineering problem</h2><p>No example project or benchmark values are loaded. Create a blank project, upload your data, choose a discipline or explore an example explicitly.</p></div><div class="home-actions"><button class="primary-button" data-home="new-project">CREATE NEW PROJECT</button><button class="tool-button" data-home="import">UPLOAD MY DATA</button><button class="tool-button" data-home="discipline">CHOOSE ENGINEERING DISCIPLINE</button><button class="tool-button" data-home="analytics">ANALYZE A DATASET</button><button class="tool-button" data-home="projects">OPEN MY PROJECTS</button><button class="tool-button" data-home="examples">EXPLORE EXAMPLES</button><button class="tool-button" data-home="assistant">ASK AXIOMFORGE AI</button></div><div class="module-disclaimer">Customer data is entered or uploaded by the user. Engineering examples remain separate and are never silently injected into a new project.</div>`; host.querySelectorAll('[data-home]').forEach(b=>b.onclick=()=>{ const target=b.dataset.home; const nav=document.querySelector(`[data-view="${target}"]`); if(nav) nav.click(); }); return; }
  if(view==='new-project') { host.innerHTML=`<div class="module-header"><div><span class="eyebrow">PROJECT SETUP</span><h2>Create a blank project</h2><p>Define project identity first. No model, calculations or example values are loaded.</p></div><span class="status-chip">BLANK</span></div><div class="input-grid project-form"><label>Project name<input id="projectName" type="text" required placeholder="e.g. North plant upgrade"><small>required</small></label><label>Location<input id="projectLocationInput" type="text" placeholder="City / country"><small>optional</small></label><label>Primary discipline<select id="projectDiscipline"><option>General engineering</option><option>Water & drainage</option><option>Airflow & ventilation</option><option>Structural engineering</option><option>Clean energy</option><option>Business analytics</option></select></label></div><div class="module-actions"><button class="primary-button" id="createBlankProject">CREATE BLANK PROJECT</button></div><div id="projectMessage" class="module-disclaimer">A blank project starts without customer data. Add inputs from a discipline workspace or upload source data.</div>`; $('createBlankProject').onclick=async()=>{ const name=$('projectName').value.trim(); if(!name){$('projectMessage').textContent='Project name is required.';return;} let project={id:'project-'+Date.now(),name,discipline:$('projectDiscipline').value,location:$('projectLocationInput').value||'Not specified',updatedAt:new Date().toISOString(),inputs:{},record:null}; if(currentUser){const cloud=await cloudUpsertProject(project); if(cloud) project={...project,id:cloud.id};} saveProject(project); setContext(name,`${project.discipline} · blank project`,true); $('projectRef').textContent=project.id; $('projectLocation').textContent=project.location; $('projectBasis').textContent='User-created blank project'; $('projectStatus').textContent='Draft · saved locally'; $('projectDisclaimer').textContent='USER PROJECT · NO RESULTS'; $('projectMessage').textContent='Blank project saved persistently in this browser. Enter or upload data to continue.'; }; return; }
  if(view==='examples') { host.innerHTML=`<div class="module-header"><div><span class="eyebrow">OPT-IN EXAMPLES</span><h2>Example Projects</h2><p>Examples are isolated from customer projects. Select one explicitly to load its data and visualizations.</p></div><span class="status-chip warning">EXPLICIT LOAD</span></div><div class="module-cards"><article class="module-card"><span>MBR-26-001</span><strong>Mbarara Smart Residence</strong><small>Two-storey BIM example · provisional written-brief reconstruction</small><button class="tool-button" id="openMbarara">OPEN EXAMPLE IN BIM STUDIO</button></article><article class="module-card"><span>CALCULATION EXAMPLES</span><strong>Engineering solver fixtures</strong><small>Backend-only reference inputs remain in tests; no customer project is created.</small></article></div><div class="module-disclaimer">Example data is clearly labeled and loaded only after an explicit user action.</div>`; $('openMbarara').onclick=()=>{ exampleRequested=true; document.querySelector('[data-view="model"]').click(); }; return; }
  if(view==='account') { renderAccountWorkspace(host); return; }
  if(view==='import') { renderImportWorkspace(host); return; }
  if(view==='projects') { const local=getProjects(); let cloud=[]; if(currentUser){ const response=await supabase.from('projects').select('id,name,discipline,location,updated_at').order('updated_at',{ascending:false}); cloud=response.data||[]; } const records=[...cloud.map(x=>({...x,cloud:true,updatedAt:x.updated_at})),...local.filter(x=>!x.cloudId)]; host.innerHTML=`<div class="module-header"><div><span class="eyebrow">PERSISTENT PROJECT REGISTER</span><h2>My Projects</h2><p>${currentUser?'Private Supabase records are available across signed-in devices.':'Sign in to view and reopen private cloud projects across devices.'}</p></div><span class="status-chip">${currentUser?'CLOUD + LOCAL':'LOCAL ONLY'}</span></div>${records.length?`<div class="project-list">${records.map(x=>`<article class="module-card"><span>${x.discipline||'General engineering'}${x.cloud?' · PRIVATE CLOUD':''}</span><strong>${x.name}</strong><small>${x.location||'No location'} · updated ${new Date(x.updatedAt||x.updated_at).toLocaleString()}</small><button class="tool-button" data-open-project="${x.id}" data-cloud="${x.cloud?'true':'false'}">REOPEN PROJECT</button></article>`).join('')}</div>`:'<div class="module-disclaimer">No saved projects available. Create a blank project to begin.</div>'}<div class="module-disclaimer">Local projects remain preserved. Cloud projects are protected by Supabase Auth and Row Level Security.</div>`; host.querySelectorAll('[data-open-project]').forEach(b=>b.onclick=()=>{const id=b.dataset.openProject; const x=b.dataset.cloud==='true'?cloud.find(p=>p.id===id):getProjects().find(p=>p.id===id); if(x){localStorage.setItem('axiomforge.activeProject',id);setContext(x.name,`${x.discipline||'General engineering'} · reopened project`,true);$('projectRef').textContent=id;$('projectLocation').textContent=x.location||'Not specified';$('projectBasis').textContent='Private cloud project';$('projectStatus').textContent='Reopened';$('projectDisclaimer').textContent='USER PROJECT · CLOUD-SAVED';}}); return; }
  if(view==='water') { renderWaterWorkspace(host); return; }
  if(view==='simulation') { renderAirflowWorkspace(host); return; }
  if(view==='energy') { renderEnergyWorkspace(host); return; }
  const m=MODULES[view] || genericModule(view); host.innerHTML=`<div class="module-header"><div><span class="eyebrow">${m.eyebrow}</span><h2>${m.title}</h2><p>${m.description}</p></div><span class="status-chip warning">${m.status}</span></div><div class="module-cards">${m.cards.map(c=>`<article class="module-card"><span>${c[0]}</span><strong>${c[1]}</strong><small>${c[2]}</small></article>`).join('')}</div><div class="module-disclaimer">Enter or upload project data before this workspace can calculate a result. Unsupported solvers remain clearly marked as roadmap.</div>`;
}
function renderWaterWorkspace(host) { host.innerHTML=`<div class="module-header"><div><span class="eyebrow">USER-DRIVEN HYDRAULICS</span><h2>Water & Drainage Engineering</h2><p>Single-pipe Hazen-Williams screen. Enter every required parameter; no benchmark values are supplied.</p></div><span class="status-chip">INPUT REQUIRED</span></div><div class="input-grid domain-form">${formField('waterHead','Reservoir head','m', 'placeholder="required"')}${formField('waterDemand','Flow demand','L/s','placeholder="required"')}${formField('waterLength','Pipe length','m','placeholder="required"')}${formField('waterDiameter','Pipe diameter','mm','placeholder="required"')}${formField('waterRoughness','Roughness coefficient C','—','placeholder="required"')}${formField('waterRise','Elevation rise','m','placeholder="required"')}</div><div class="module-actions"><button class="primary-button" id="calculateWater">CALCULATE FROM MY INPUTS</button></div><div id="waterResult" class="result-panel">Enter the network parameters and calculate to see the hydraulic grade screen.</div>`; $('calculateWater').onclick=calculateWater; }
async function calculateWater(){ const result=$('waterResult'); const check=requiredNumbers(['waterHead','waterDemand','waterLength','waterDiameter','waterRoughness','waterRise'],['Reservoir head','Flow demand','Pipe length','Pipe diameter','Roughness coefficient','Elevation rise'],[0,0,0,0,0,-500]); if(check.error){result.textContent=check.error;return;} const v=check.values; const body={reservoir_head_m:v[0],demand_lps:v[1],pipe_length_m:v[2],pipe_diameter_mm:v[3],roughness_c:v[4],elevation_rise_m:v[5]}; const r=await fetch(API+'/api/water/network',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)}); const d=await r.json(); if(!r.ok){result.textContent=d.detail||d.error||'The water inputs are invalid.';return;} saveProject({id:localStorage.getItem('axiomforge.activeProject')||'water-'+Date.now(),name:'Water analysis',discipline:'Water & drainage',updatedAt:new Date().toISOString(),inputs:body,outputs:d.outputs,record:d.record}); result.innerHTML=`<div class="result-header"><strong>${d.record.calculation_id} · ${d.record.status.toUpperCase()}</strong><span>${d.record.solver}</span></div>${svgWater(d)}<div class="unit-result-grid"><span>Head loss <b>${d.outputs.headloss_m} m</b></span><span>Residual head <b>${d.outputs.residual_head_m} m</b></span><span>Velocity <b>${d.outputs.velocity_m_s} m/s</b></span></div><small>${d.record.limitations.join('; ')}</small>`; }
function renderAirflowWorkspace(host){ host.innerHTML=`<div class="module-header"><div><span class="eyebrow">USER-DRIVEN VENTILATION</span><h2>Airflow & Ventilation</h2><p>Steady room air-change screen. Enter room geometry, ventilation and sensible load; this is not CFD.</p></div><span class="status-chip">INPUT REQUIRED</span></div><div class="input-grid domain-form">${formField('airLength','Room length','m','placeholder="required"')}${formField('airWidth','Room width','m','placeholder="required"')}${formField('airHeight','Room height','m','placeholder="required"')}${formField('airACH','Air changes / hour','ACH','placeholder="required"')}${formField('airInlet','Inlet area','m²','placeholder="required"')}${formField('airLoad','Sensible load','kW','placeholder="required"')}</div><div class="module-actions"><button class="primary-button" id="calculateAir">CALCULATE FROM MY INPUTS</button></div><div id="airResult" class="result-panel">Enter room and ventilation parameters and calculate to see airflow indicators.</div>`; $('calculateAir').onclick=calculateAir; }
async function calculateAir(){ const result=$('airResult'); const check=requiredNumbers(['airLength','airWidth','airHeight','airACH','airInlet','airLoad'],['Room length','Room width','Room height','Air changes','Inlet area','Sensible load'],[0,0,0,0,0,0]); if(check.error){result.textContent=check.error;return;} const v=check.values; const body={room_length_m:v[0],room_width_m:v[1],room_height_m:v[2],air_changes_per_hour:v[3],inlet_area_m2:v[4],sensible_load_kw:v[5]}; const r=await fetch(API+'/api/airflow/room',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)}); const d=await r.json(); if(!r.ok){result.textContent=d.detail||d.error||'The airflow inputs are invalid.';return;} saveProject({id:localStorage.getItem('axiomforge.activeProject')||'air-'+Date.now(),name:'Airflow analysis',discipline:'Airflow & ventilation',updatedAt:new Date().toISOString(),inputs:body,outputs:d.outputs,record:d.record}); result.innerHTML=`<div class="result-header"><strong>${d.record.calculation_id} · ${d.record.status.toUpperCase()}</strong><span>Room analytical screen</span></div>${svgAir(d)}<div class="unit-result-grid"><span>Flow <b>${d.outputs.flow_m3_s} m³/s</b></span><span>Inlet velocity <b>${d.outputs.inlet_velocity_m_s} m/s</b></span><span>Sensible ΔT <b>${d.outputs.sensible_temperature_rise_c} °C</b></span></div><small>${d.record.limitations.join('; ')}</small>`; }
function renderEnergyWorkspace(host){ host.innerHTML=`<div class="module-header"><div><span class="eyebrow">USER-DRIVEN ENERGY</span><h2>Clean Energy Engineering</h2><p>Enter demand, PV and battery inputs to generate a traceable screening result.</p></div><span class="status-chip">INPUT REQUIRED</span></div><div class="input-grid domain-form">${formField('energyUse','Annual energy demand','kWh','placeholder="required"')}${formField('energyPV','PV capacity','kW','placeholder="required"')}${formField('energySun','Peak sun hours','h/day','placeholder="required"')}${formField('energyBattery','Battery capacity','kWh','placeholder="required"')}</div><div class="module-actions"><button class="primary-button" id="calculateEnergy">CALCULATE FROM MY INPUTS</button></div><div id="energyResult" class="result-panel">Enter energy inputs and calculate to see generation, coverage and grid import.</div>`; $('calculateEnergy').onclick=calculateEnergy; }
async function calculateEnergy(){ const result=$('energyResult'); const check=requiredNumbers(['energyUse','energyPV','energySun','energyBattery'],['Annual energy demand','PV capacity','Peak sun hours','Battery capacity'],[0,0,0,0]); if(check.error){result.textContent=check.error;return;} const v=check.values; const r=await fetch(API+'/api/energy/solar',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({annual_consumption_kwh:v[0],pv_kw:v[1],peak_sun_hours:v[2],battery_kwh:v[3]})}); const d=await r.json(); if(!r.ok){result.textContent=d.detail||'The energy inputs are invalid.';return;} saveProject({id:localStorage.getItem('axiomforge.activeProject')||'energy-'+Date.now(),name:'Energy analysis',discipline:'Clean energy',updatedAt:new Date().toISOString(),inputs:d.inputs,outputs:d.outputs,record:d.record}); result.innerHTML=`<div class="result-header"><strong>${d.record.calculation_id} · ${d.record.status.toUpperCase()}</strong><span>PV + battery screen</span></div>${svgEnergy(d)}<div class="unit-result-grid"><span>Generation <b>${d.outputs.annual_generation_kwh} kWh/year</b></span><span>Coverage <b>${d.outputs.annual_consumption_coverage}%</b></span><span>Grid import <b>${d.outputs.grid_import_kwh} kWh/year</b></span></div><small>${d.record.limitations.join('; ')}</small>`; }
function bindUI() {
  $('modelCanvas').addEventListener('pointerdown', onPointer); window.addEventListener('resize', resize);
  $('modeArchitectural').onclick = () => { isTechnical = false; $('modeArchitectural').classList.add('active'); $('modeTechnical').classList.remove('active'); $('workspaceTitle').textContent = 'Architectural model'; applyPreset('render'); };
  $('modeTechnical').onclick = () => { isTechnical = true; $('modeTechnical').classList.add('active'); $('modeArchitectural').classList.remove('active'); $('workspaceTitle').textContent = 'Technical BIM inspection'; applyPreset('technical'); };
  $('cameraToggle').onclick = setCameraMode; $('resetView').onclick = resetView;
  $('floorGround').onclick = () => { floors.ground = !floors.ground; $('floorGround').classList.toggle('active', floors.ground); applyFloorVisibility(); };
  $('floorUpper').onclick = () => { floors.upper = !floors.upper; $('floorUpper').classList.toggle('active', floors.upper); applyFloorVisibility(); };
  $('sectionSlider').oninput = e => setSection(e.target.value); $('measureButton').onclick = () => { measureMode = !measureMode; measureStart = null; $('measureButton').classList.toggle('active', measureMode); $('measureLabel').textContent = measureMode ? 'Pick two components to measure' : ''; $('measureLabel').classList.toggle('hidden', !measureMode); };
  $('explodeButton').onclick = () => { exploded = !exploded; $('explodeButton').classList.toggle('active', exploded); modelRoot.children.forEach(o => { if (o.userData?.floor === 'upper') o.position.y += exploded ? 1.4 : -1.4; }); };
  $('materialPreset').onchange = e => applyPreset(e.target.value);
  document.querySelectorAll('.overlay-option').forEach(btn => btn.onclick = () => { document.querySelectorAll('.overlay-option').forEach(x => x.classList.remove('active')); btn.classList.add('active'); const mode = btn.dataset.overlay; if (mode === 'solar') { addSolarOverlay(); } if (mode === 'structure') addStructureOverlay(); modelRoot.traverse(o => { if (o.userData.overlay) o.visible = o.userData.overlay === mode; }); });
  $('runSolar').onclick = runSolar;
  document.querySelectorAll('.nav').forEach(btn => btn.onclick = () => { document.querySelectorAll('.nav').forEach(x => x.classList.toggle('active', x === btn)); const view = btn.dataset.view; renderWorkspace(view); if (view === 'model') $('workspaceTitle').textContent = 'Architectural model'; });
}
async function runSolar() { $('solverStatus').textContent = 'RUNNING'; const body = { annual_consumption_kwh: +$('consumption').value, pv_kw: +$('pv').value, peak_sun_hours: +$('sunHours').value, battery_kwh: +$('battery').value }; const response = await fetch(API + '/api/energy/solar', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(body) }); const d = await response.json(); lastSolar = d; $('generation').textContent = d.outputs.annual_generation_kwh.toLocaleString(); $('coverage').textContent = d.outputs.annual_consumption_coverage + '%'; $('gridImport').textContent = d.outputs.grid_import_kwh.toLocaleString(); $('solverStatus').textContent = d.record.status.toUpperCase(); $('solverRecord').textContent = `${d.record.solver} · ${d.record.methodology} · ${d.record.status}. Model overlay is a screening visualization, not a verified PV layout.`; }
initMaterials(); createScene(); bindUI(); renderWorkspace('overview'); initAuth();
